1	interface Item {
2	  type: string;
3	  cursed?: boolean;
4	  enchantment?: number;
5	}
6	
7	interface QuoteStep {
8	  op: "quote";
9	  items: Item[];
10	}
11	
12	interface Scenario {
13	  customer: { yearsWithMHPCO: number };
14	  steps: QuoteStep[];
15	}
16	
17	interface QuoteResult {
18	  premium: number;
19	}
20	
21	const BASE_PREMIUM: Record<string, number> = {
22	  sword: 100,
23	  amulet: 60,
24	  staff: 80,
25	  potion: 40,
26	  rune: 25,
27	};
28	
29	const PROCESSING_FEE = 5;
30	const FIRST_INSURANCE_SURCHARGE = 0.1;
31	
32	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
33	const COMPONENT_UNIT_PREMIUM = 25;
34	const COMPONENT_BLOCK_SIZE = 3;
35	const COMPONENT_BLOCK_PREMIUM = 60;
36	
37	const componentGroupBase = (count: number): number =>
38	  count === COMPONENT_BLOCK_SIZE
39	    ? COMPONENT_BLOCK_PREMIUM
40	    : count * COMPONENT_UNIT_PREMIUM;
41	
42	const componentsBase = (components: Item[]): number => {
43	  const countsByType = new Map<string, number>();
44	  for (const component of components) {
45	    countsByType.set(component.type, (countsByType.get(component.type) ?? 0) + 1);
46	  }
47	  return [...countsByType.values()].reduce(
48	    (total, count) => total + componentGroupBase(count),
49	    0,
50	  );
51	};
52	
53	const isComponent = (item: Item): boolean =>
54	  COMPONENT_TYPES.has(item.type);
55	
56	const itemsBase = (items: Item[]): number => {
57	  const mainBase = items
58	    .filter((item) => !isComponent(item))
59	    .reduce((sum, item) => sum + BASE_PREMIUM[item.type], 0);
60	  return mainBase + componentsBase(items.filter(isComponent));
61	};
62	
63	const CURSE_SURCHARGE = 0.5;
64	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
65	const HIGH_ENCHANTMENT_THRESHOLD = 5;
66	
67	// Sum `rate * base premium` for every item matching `applies`. The additive
68	// per-item form keeps each surcharge a flat term so quotePremium stays additive
69	// (see the float-drift note there).
70	const itemSurcharge = (
71	  items: Item[],
72	  applies: (item: Item) => boolean,
73	  rate: number,
74	): number =>
75	  items.reduce(
76	    (sum, item) => sum + (applies(item) ? BASE_PREMIUM[item.type] * rate : 0),
77	    0,
78	  );
79	
80	const curseSurcharge = (items: Item[]): number =>
81	  itemSurcharge(items, (item) => item.cursed === true, CURSE_SURCHARGE);
82	
83	const highEnchantmentSurcharge = (items: Item[]): number =>
84	  itemSurcharge(
85	    items,
86	    (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
87	    HIGH_ENCHANTMENT_SURCHARGE,
88	  );
89	
90	const LOYALTY_DISCOUNT = 0.2;
91	const LOYALTY_THRESHOLD_YEARS = 2;
92	const FOLLOWUP_DISCOUNT = 0.15;
93	
94	const loyaltyDiscount = (base: number, yearsWithMHPCO: number): number =>
95	  yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS ? base * LOYALTY_DISCOUNT : 0;
96	
97	const followupDiscount = (base: number, isFollowup: boolean): number =>
98	  isFollowup ? base * FOLLOWUP_DISCOUNT : 0;
99	
100	// Always-on surcharge charged on every policy, expressed as a flat term so
101	// quotePremium stays additive (see the float-drift note there).
102	const firstInsuranceSurcharge = (base: number): number =>
103	  base * FIRST_INSURANCE_SURCHARGE;
104	
105	const quotePremium = (
106	  items: Item[],
107	  yearsWithMHPCO: number,
108	  isFollowup: boolean,
109	): number => {
110	  const base = itemsBase(items);
111	  // Sum flat terms rather than scaling `base * (1 + rate)`: the additive form
112	  // avoids IEEE-754 drift that would otherwise round wrong under Math.ceil.
113	  return Math.ceil(
114	    base +
115	      firstInsuranceSurcharge(base) +
116	      curseSurcharge(items) +
117	      highEnchantmentSurcharge(items) -
118	      loyaltyDiscount(base, yearsWithMHPCO) -
119	      followupDiscount(base, isFollowup) +
120	      PROCESSING_FEE,
121	  );
122	};
123	
124	export const runScenario = (scenario: Scenario): { results: QuoteResult[] } => {
125	  const results = scenario.steps.map((step, index) => {
126	    // Every quote after the first is a follow-up contract; the map index is
127	    // already the count of quotes seen so far, so no separate counter is needed.
128	    const isFollowup = index > 0;
129	    return {
130	      premium: quotePremium(step.items, scenario.customer.yearsWithMHPCO, isFollowup),
131	    };
132	  });
133	  return { results };
134	};
